inp={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
out={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# normalize and transformations
for name,fn in [('id',lambda r,c:(r,c)),('rot90',lambda r,c:(c,-r)),('rot180',lambda r,c:(-r,-c)),('rot270',lambda r,c:(-c,r)),('flipH',lambda r,c:(r,-c)),('flipV',lambda r,c:(-r,c)),('diag',lambda r,c:(c,r)),('anti',lambda r,c:(-c,-r))]:
 s=[fn(*p) for p in inp]; mr=min(x for x,y in s); mc=min(y for x,y in s); norm={(x-mr,y-mc) for x,y in s}
 t=[fn(*p) for p in out]; nr=min(x for x,y in t); nc=min(y for x,y in t); norm2={(x-nr,y-nc) for x,y in t}
 print(name,norm==norm2, (max(x for x,y in norm)+1,max(y for x,y in norm)+1))
